// Binary search (table is sorted by real name); index into the table, or -1.
inline int BNM_LiveMapIndex(const char* name) {
    int lo = 0, hi = kBNMLiveNameMapCount - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        int c = strcmp(name, kBNMLiveNameMap[mid].real);
        if (c == 0) return mid;
        if (c < 0) hi = mid - 1; else lo = mid + 1;
    }
    return -1;
}

inline const char* BNM_LiveMapLookup(const char* name) {
    int lo = 0, hi = kBNMLiveNameMapCount - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        int c = strcmp(name, kBNMLiveNameMap[mid].real);
        if (c == 0) return kBNMLiveNameMap[mid].live;
        if (c < 0) hi = mid - 1; else lo = mid + 1;
    }
    return nullptr;
}
